define("block_maristtela/context",["jquery"],function(a){const b=function(b){const c=b&&b.courseid||0,d=a(".maristtela-context");if(!d.length||!c)return;const e=M.cfg.wwwroot+"/blocks/maristtela/api/context.php?courseid="+c;d.addClass("loading"),a.getJSON(e).done(function(b){const c=d.find('[data-box="grades"] .box-body');if(c.empty(),b.grades&&b.grades.length)b.grades.slice(0,6).forEach(function(a){const b=null!==a.grade?a.grade+"/"+(a.grademax||"-"):"—";c.append('<div class="row-item"><span>'+a.name+"</span><strong>"+b+"</strong></div>")});else c.append('<div class="empty">Sem notas disponíveis.</div>');const e=d.find('[data-box="upcoming"] .box-body');if(e.empty(),b.upcoming&&b.upcoming.length)b.upcoming.sort(function(a,b){return a.deadline-b.deadline}).slice(0,6).forEach(function(b){const c=new Date(1e3*b.deadline).toLocaleString(),d=b.url||"#";e.append('<a class="row-item" href="'+d+'"><span>'+b.title+"</span><em>"+c+"</em></a>")});else e.append('<div class="empty">Sem prazos próximos.</div>');const f=d.find('[data-box="forums"] .box-body');b.forums&&b.forums.length?(f.empty(),b.forums.slice(0,6).forEach(function(b){const c=new Date(1e3*b.timemodified).toLocaleString();f.append('<a class="row-item" href="'+b.url+'"><span>'+b.forum+": "+b.discussion+'</span><em>'+c+"</em></a>")})):f.html('<div class="empty">Sem discussões recentes.</div>')}).fail(function(){d.find(".box-body").html('<div class="empty">Falha ao carregar o contexto.</div>')}).always(function(){d.removeClass("loading")})};return{initContext:b}});
